# ==============================================================================# IOTEC MISSION CONTROL# 008_SERVICE_MANAGER.py# ==============================================================================import jsonfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentREGISTRY = ROOT / "MISSION_CONTROL" / "config" / "service_registry.json"STATUS = ROOT / "MISSION_CONTROL" / "config" / "services_status.json"with open(REGISTRY, encoding="utf-8") as f:    registry = json.load(f)services = registry["services"]online = 0offline = 0critical = 0for service in services:    if service["status"] == "ONLINE":        online += 1    else:        offline += 1    if service["critical"]:        critical += 1summary = {    "generated_at": datetime.now().isoformat(),    "total_services": len(services),    "online": online,    "offline": offline,    "critical": critical,    "health": round((online / len(services)) * 100, 2)}with open(STATUS, "w", encoding="utf-8") as f:    json.dump(summary, f, indent=4, ensure_ascii=False)print("=" * 80)print("SERVICE MANAGER")print("=" * 80)print(f"TOTAL.............: {summary['total_services']}")print(f"ONLINE............: {summary['online']}")print(f"OFFLINE...........: {summary['offline']}")print(f"CRÃTICOS..........: {summary['critical']}")print(f"HEALTH............: {summary['health']} %")print("=" * 80)

